import type { NodeMap } from '../compiler/types.ts';
import { languageApiName } from '../grammars.ts';

export interface EmitIndexConfig {
	grammar: string;
	nodeMap: NodeMap;
	portable?: boolean;
}

export function emitDescriptor(config: EmitIndexConfig): string {
	const api = languageApiName(config.grammar);
	const self = config.grammar;
	return [
		'// Auto-generated by @sittir/codegen — do not edit',
		'',
		"import type { ApiSurface, Engine as EngineOf, Language } from '@sittir/types';",
		`import type { ${api} } from './api.js';`,
		"import { languageGuards } from '@sittir/common/language';",
		`import * as ${self} from './descriptor.js';`,
		"import { TSKindId } from './kinds.js';",
		"import { guardsWith } from './is.js';",
		...(config.portable === true
			? [
					"import { portable, portableGuardsOf } from '@sittir/common/portable';",
					"import type { PortableIs, PortableKinds } from './portable.js';"
				]
			: []),
		'',
		"export type * from './types.js';",
		"export type * from './options.js';",
		"export type { IsGuards } from './is.js';",
		`export type { ${api} } from './api.js';`,
		"export type { CSTNode } from '@sittir/types';",
		`export type Engine<M extends ApiSurface = 'default'> = EngineOf<${api}, M>;`,
		'',
		`export const name = '${config.grammar}';`,
		`export const fileTypes: readonly string[] = Object.freeze(${JSON.stringify(config.nodeMap.fileTypes)});`,
		...(config.portable === true
			? [
					'export const kinds: typeof TSKindId & { readonly portable: PortableKinds } = Object.freeze({ ...TSKindId, portable: portable.kinds as PortableKinds });',
					`export const is = languageGuards(guardsWith, ${self}, (language) => ({ portable: portableGuardsOf(language) as PortableIs }));`
				]
			: ['export const kinds = TSKindId;', `export const is = languageGuards(guardsWith, ${self});`]),
		`export const load: Language<${api}>['load'] = () => import('./api.js').then((m) => m.hooks);`,
		`export const createEngine: Language<${api}>['createEngine'] = (options) => import('@sittir/common').then((m) => m.createEngine(${self}, options));`,
		'',
		`void (${self} satisfies Language<${api}>);`,
		''
	].join('\n');
}

export function emitArenaDescriptor(grammar: string): string {
	const api = languageApiName(grammar);
	return [
		'// Auto-generated by @sittir/codegen — do not edit',
		'',
		"import type { CreateEngineOptions, Engine } from '@sittir/types';",
		`import type { ${api} } from './api.js';`,
		`import * as ${grammar} from './descriptor.js';`,
		'',
		"export type * from './descriptor.js';",
		`export type { ${api} } from './api.js';`,
		'',
		`function createEngine<const R extends ${api}['options'] = ${api}['options']>(options?: CreateEngineOptions<${api}, R>): Promise<Engine<${api}>> {`,
		`\treturn ${grammar}.createEngine<R>({ ...options, nodeStorage: options?.nodeStorage ?? 'arena' });`,
		'}',
		'',
		`/** The ${grammar} descriptor whose \`createEngine\` reads a parsed tree's nodes as records (\`nodeStorage: 'arena'\`). Its \`is\`, \`kinds\` and \`load\` are the descriptor's own. */`,
		`const arena: typeof ${grammar} = Object.freeze({ ...${grammar}, createEngine });`,
		'export default arena;',
		''
	].join('\n');
}

export function emitIndex(): string {
	return [
		'// Auto-generated by @sittir/codegen — do not edit',
		'',
		"export * as default from './descriptor.js';",
		"export type * from './descriptor.js';",
		''
	].join('\n');
}
